"""Cleaning Wikipedia edit summaries into usable changelog targets."""

from __future__ import annotations

import re

# "/* Section name */ rest" -> section autocomment added by the editor UI.
AUTOCOMMENT_RE = re.compile(r"/\*\s*(.*?)\s*\*/")

# Summaries that are generated by MediaWiki or tools, or that only make sense
# with information the diff doesn't contain (usernames, revision ids).
DROP_RE = re.compile(
    r"""^(?:
        ←                                   # MediaWiki auto-summaries
      | undid\b | undo\b | revert | rv\b | rvv\b
      | reverted\b | restored\b | rollback
      | moved\ page | page\ moved
    )""",
    re.IGNORECASE | re.VERBOSE,
)
# Interwiki/maintenance bots; their summaries often start with a version tag,
# e.g. "r2.6.4) (Robot: Adding [[su:Maroko]]", so search rather than match.
BOT_RE = re.compile(r"\b(?:ro)?bot\b|pywikibot", re.IGNORECASE)
PERSONAL_RE = re.compile(
    r"\[\[(?:user|user talk|special:contributions)[:/]", re.IGNORECASE
)


def clean_summary(comment: str | None, keep_bots: bool = False) -> str | None:
    """Return a cleaned summary, or None if the edit should be skipped."""
    if not comment:
        return None
    text = AUTOCOMMENT_RE.sub(" ", comment)
    text = " ".join(text.split())
    text = text.lstrip(":-–—,; ").strip()
    if len(text) < 3:
        return None
    if PERSONAL_RE.search(text):
        return None
    if DROP_RE.match(text):
        return None
    if not keep_bots and BOT_RE.search(text):
        return None
    return text
